#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_preorder_display_non_empty_tree(void) {
    node *root = NULL;
    int values[] = {10, 5, 15, 3, 7, 12, 18};
    int size = sizeof(values) / sizeof(values[0]);

    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    stdout_capture_t *cap = capture_stdout_start();
    preorder_display(root);
    char *output = capture_stdout_stop(cap);

    TEST_ASSERT_NOT_NULL(output);
    TEST_ASSERT_NOT_NULL(strstr(output, "10"));
    TEST_ASSERT_NOT_NULL(strstr(output, "5"));
    TEST_ASSERT_NOT_NULL(strstr(output, "15"));

    free(output);
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_preorder_display_non_empty_tree);
    return UNITY_END();
}

